import React, { useState } from 'react';
import { TextField, Button, Box, Typography, Card, CardHeader, CardContent, Avatar, Grid } from '@mui/material';

function Login({ onLogin, onRegister, onBack }) {
  const [mobile, setMobile] = useState('');
  const [notRegistered, setNotRegistered] = useState(false);
  const [showMaids, setShowMaids] = useState(false);
  const [maids, setMaids] = useState([]);
  // Filter states
  const [filterWorkType, setFilterWorkType] = useState('');
  const [filterLocation, setFilterLocation] = useState('');
  const [filterStartTime, setFilterStartTime] = useState('');
  const [filterEndTime, setFilterEndTime] = useState('');

  const handleLogin = async () => {
    // Validation
    if (!mobile) {
      alert('Please enter your registered mobile number');
      return;
    }
    if (!/^\d{10}$/.test(mobile)) {
      alert('Please enter a valid 10 digit mobile number.');
      return;
    }
    // Check registration in backend
    try {
      const response = await fetch('http://localhost:5000/api/owners/check', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone: mobile })
      });
      const result = await response.json();
      if (result.status === 'success' && result.registered) {
        // Fetch maids from backend
        try {
          const maidsResponse = await fetch('http://localhost:5000/api/maids');
          const maidsJson = await maidsResponse.json();
          setMaids(Array.isArray(maidsJson.maids) ? maidsJson.maids : []);
        } catch (maidsError) {
          alert('Error fetching maids data.');
          console.error(maidsError);
        }
        setShowMaids(true);
        onLogin && onLogin(mobile);
      } else {
        setNotRegistered(true);
      }
    } catch (error) {
      alert('Error checking registration.');
      console.error(error);
    }
  };

  if (showMaids) {
    // Get unique values for dropdowns
    const workTypeOptions = Array.from(new Set(maids.flatMap(m => (m.workType ? m.workType.split(',') : [])))).filter(Boolean);
    const locationOptions = Array.from(new Set(maids.flatMap(m => (m.location ? m.location.split(',') : [])))).filter(Boolean);
    const startTimeOptions = Array.from(new Set(maids.map(m => m.startTime).filter(Boolean)));
    const endTimeOptions = Array.from(new Set(maids.map(m => m.endTime).filter(Boolean)));

    // Filter logic
    const filteredMaids = maids.filter(maid => {
      const workTypeMatch = !filterWorkType || (maid.workType && maid.workType.split(',').map(w => w.trim()).includes(filterWorkType));
      const locationMatch = !filterLocation || (maid.location && maid.location.split(',').map(l => l.trim()).includes(filterLocation));
      const startTimeMatch = !filterStartTime || maid.startTime === filterStartTime;
      const endTimeMatch = !filterEndTime || maid.endTime === filterEndTime;
      return workTypeMatch && locationMatch && startTimeMatch && endTimeMatch;
    });

    return (
      <Box sx={{ background: '#f5f6fa', minHeight: '100vh', py: 4 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
          <Typography variant="h4" sx={{ fontWeight: 700, color: '#5f27cd' }}>Available Maids</Typography>
          <Button variant="outlined" color="secondary" onClick={() => { setShowMaids(false); setMaids([]); }}>
            Logout
          </Button>
        </Box>
        {/* Filters */}
        <Box display="flex" flexWrap="wrap" gap={2} mb={4}>
          <TextField select label="Type of Work" value={filterWorkType} onChange={e => setFilterWorkType(e.target.value)} SelectProps={{ native: true }} size="small" style={{ minWidth: 170 }} InputLabelProps={{ shrink: true }}>
            <option value="">All</option>
            {workTypeOptions.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
          </TextField>
          <TextField select label="Location" value={filterLocation} onChange={e => setFilterLocation(e.target.value)} SelectProps={{ native: true }} size="small" style={{ minWidth: 170 }} InputLabelProps={{ shrink: true }}>
            <option value="">All</option>
            {locationOptions.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
          </TextField>
          <TextField select label="Available Start Time" value={filterStartTime} onChange={e => setFilterStartTime(e.target.value)} SelectProps={{ native: true }} size="small" style={{ minWidth: 170 }} InputLabelProps={{ shrink: true }}>
            <option value="">All</option>
            {startTimeOptions.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
          </TextField>
          <TextField select label="Available End Time" value={filterEndTime} onChange={e => setFilterEndTime(e.target.value)} SelectProps={{ native: true }} size="small" style={{ minWidth: 170 }} InputLabelProps={{ shrink: true }}>
            <option value="">All</option>
            {endTimeOptions.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
          </TextField>
        </Box>
        {/* Maids List */}
        {filteredMaids.length === 0 ? (
          <Typography>No maids found.</Typography>
        ) : (
          <Grid container spacing={3}>
            {filteredMaids.map((maid, idx) => (
              <Grid item xs={12} sm={6} md={4} key={idx}>
                <Card sx={{ borderRadius: 3, boxShadow: 3, p: 2, minWidth: 280, maxWidth: 350, mx: 'auto', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                  <CardHeader
                    avatar={
                      maid.photoPath ? (
                        <Avatar
                          src={maid.photoPath.startsWith('http') ? maid.photoPath : `http://localhost:5000/uploads/${maid.photoPath}`}
                          alt={maid.name}
                          sx={{ width: 56, height: 56 }}
                        />
                      ) : (
                        <Avatar sx={{ width: 56, height: 56 }}>{maid.name ? maid.name[0] : '?'}</Avatar>
                      )
                    }
                    title={<Typography variant="h6" sx={{ fontWeight: 600, textAlign: 'center', wordBreak: 'break-word' }}>{maid.name}</Typography>}
                    subheader={<Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', wordBreak: 'break-word' }}>{maid.location}</Typography>}
                    sx={{ textAlign: 'center' }}
                  />
                  <CardContent sx={{ textAlign: 'center', wordBreak: 'break-word' }}>
                    <Typography variant="body1" sx={{ mb: 1 }}><b>Phone:</b> {maid.phone}</Typography>
                    <Typography variant="body1" sx={{ mb: 1 }}><b>Type of Work:</b> {maid.workType}</Typography>
                    <Typography variant="body1" sx={{ mb: 1 }}><b>Available Start Time:</b> {maid.startTime || ''}</Typography>
                    <Typography variant="body1" sx={{ mb: 1 }}><b>Available End Time:</b> {maid.endTime || ''}</Typography>
                    <Typography variant="body1" sx={{ mb: 1 }}><b>Living House help:</b> {maid.anywhere ? 'Yes' : 'No'}</Typography>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        )}
        <Button variant="text" color="inherit" fullWidth style={{ marginTop: 32 }} onClick={onBack}>
          Back to Home
        </Button>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Login</Typography>
      <TextField
        label="Mobile Number(10 digit)"
        value={mobile}
        onChange={e => setMobile(e.target.value)}
        fullWidth
        margin="normal"
      />
      <Button variant="contained" color="primary" fullWidth onClick={handleLogin}>
        Login
      </Button>
      {notRegistered && (
        <Typography color="error" style={{ marginTop: 8 }}>
          Mobile no. is not registered, Please register
        </Typography>
      )}
      <Button variant="outlined" color="secondary" fullWidth style={{ marginTop: 16 }} onClick={onRegister}>
        Register
      </Button>
      <Button variant="text" color="inherit" fullWidth style={{ marginTop: 16 }} onClick={onBack}>
        Back to Home
      </Button>
    </Box>
  );
}

export default Login;
